import sys

def main():
    tok = sys.stdin.read().split()
    n = len(tok)
    level = [0]
    i = 1
    prev_color = int(tok[0])
    ok = True
    while level and ok:
        nxt = []
        # every node of this level has two child slots, taken from the token stream in order
        for _ in level:
            for _side in range(2):
                if i < n:
                    if tok[i] != 'null':
                        nxt.append(i)
                    i += 1
        if nxt:
            c = int(tok[nxt[0]])
            if c == prev_color or any(int(tok[j]) != c for j in nxt):
                ok = False
            prev_color = c
        level = nxt
    print('true' if ok else 'false')

